INSERT INTO codebook (table_name, column_name, value, meaning) VALUES
    ('participants', 'l2_status', '0', 'L1 speaker'),
    ('participants', 'l2_status', '1', 'L2 speaker'),
    ('participants', 'l2_status', '9', 'Encoded missing category: L1/L2 status was not recorded, but the database stores the integer 9 rather than SQL NULL. Find these participants with WHERE l2_status = 9; IS NULL will not find them. Exclude from L1/L2 comparisons.'),
    ('participants', 'proficiency_score', 'NULL', 'Structural missingness stored as SQL NULL: the participant did not take the proficiency test. Find these participants with WHERE participants.proficiency_score IS NULL; do not compare with the test ''NULL'', an empty string, or the encoded value 9.'),
    ('participants', 'age', 'NULL', 'Age not recorded'),
    ('participants', 'recruitment_site', 'NULL', 'Recruitment site not recorded'),
    ('participants', 'device', '__COLUMN__', 'Raw, intentionally unnormalized device label recorded when the test was completed. Normalize through the device-label mapping before grouped analysis'),
    ('participants', 'recruitment_wave', 'wave1', 'First recruitment cohort in chronological order (sequence 1), recruited during Fall 2025; precedes wave2'),
    ('participants', 'recruitment_wave', 'wave2', 'Second recruitment cohort in chronological order (sequence 2), recruited during Winter 2025; precedes wave3'),
    ('participants', 'recruitment_wave', 'wave3', 'Third recruitment cohort in chronological order (sequence 3), recruited during Spring 2026; precedes wave4'),
    ('participants', 'recruitment_wave', 'wave4', 'Fourth recruitment cohort in chronological order (sequence 4), recruited during Summer 2026'),
    ('participants', 'list_number', '1', 'Counterbalanced list 1; not sequence'),
    ('participants', 'list_number', '2', 'Counterbalanced list 2; not sequence'),
    ('participants', 'list_number', '3', 'Counterbalanced list 3; not sequence'),
    ('participants', 'list_number', '4', 'Counterbalanced list 4; not sequence'),
    ('stimuli', 'condition', '__COLUMN__', 'Raw categorical contrast derived from the target word surprisal. Values below 5.0 bits belong to low_surprisal; values at or above 5.0 bits belong to high_surprisal. A specified percent of the labels are documented noncanonical variants and must be normalized before grouping.'),
    ('stimuli', 'sentence_num', '__COLUMN__', 'One-based sentence position within a story. Numbering restarts at 1 for each story; identify a sentence using story_id and sentence_num together.'),
    ('stimuli', 'word_position', '__COLUMN__', 'One-based word position within a sentence. Numbering restarts at 1 for each sentence, so word_position = 1 means the first word of a sentence, not necessarily the first word of a story.'),
    ('stimuli', 'frequency', '__COLUMN__', 'Continuous Zipf word-frequency score: log10 occurrences per billion words. Higher values means more frequent words, and an increase of 1 represents approximately ten times greater frequency.'),
    ('stimuli', 'length', '__COLUMN__', 'Number of Unicode characters in the stored word token, calculated with char_length. Characters such as an apostrophe count when they are a part of the stored token; this is not byte length, syllable count, or token count.'),
    ('stimuli', 'surprisal', '__COLUMN__', 'Continuous contextual surprisal in bits, calculated as -log2 P(word | preceding context). Higher values mean the word was less predictable; an increase of 1 bit means half the conditional probability.'),
    ('stimuli', 'condition', 'low_surprisal', 'Canonical condition for a target word with surprisal below 5.0 bits.'),
    ('stimuli', 'condition', 'high_surprisal', 'Canonical condition for a target word with surprisal at or above 5.0 bits.'),
    ('stimuli', 'condition', 'LOW_SURPRISAL', 'Noncanonical label variant of low_surprisal, deliberately emitted for a specified percent of the rows of this condition. Normalize to low_surprisal before grouping.'),
    ('stimuli', 'condition', 'HIGH_SURPRISAL', 'Noncanonical label variant of high_surprisal, deliberately emitted for a specified percent of the rows of this condition. Normalize to high_surprisal before grouping.'),
    ('comprehension_questions', 'correct_answer', '__COLUMN__', 'Reference answer used to score comprehension. Compare comprehension_questions.correct_answer with comprehension_responses.response after trimming outer whitespace, collapsing repeated whitespace, and converting both values to lowercase; punctuation and diacritics remain significant.'),
    ('comprehension_responses', 'response', '__COLUMN__', 'Participant answer preserved as entered. Join to comprehension_questions to obtain correct_answer. The response is correct when its whitespace- and case-normalized value equals the similarly normalized correct_answer; matching is not case-sensitive, but punctuation and diacritics remain significant.'),
    ('responses', 'onset_ms', '__COLUMN__', 'milliseconds from session start; used with offset_ms to find per-word reading time in milliseconds with formula offset_ms - onset_ms; onset_ms must be nonnegative and strictly less than offset_ms.'),
    ('responses', 'offset_ms', '__COLUMN__', 'milliseconds from session start; used with onset_ms to find per-word reading time in milliseconds with formula offset_ms - onset_ms; offset_ms must be strictly greater than onset_ms.'),
    ('dataset_versions', 'validation_status', 'pending', 'validation pending'),
    ('dataset_versions', 'validation_status', 'passed', 'validation passed'),
    ('dataset_versions', 'validation_status', 'failed', 'validation failed'),
    ('dataset_versions', 'dataset_version', '__COLUMN__', 'uses v{#} as the convention'),
    ('codebook', 'value', '__COLUMN__', 'Reserved codebook marker indicating that the row documents a column as a whole rather than a literal value stored in that column.'),
    ('codebook', 'value', 'NULL', 'Codebook notation for SQL NULL, for the four-character text value NULL. Its precise analytical meaning is defined separately for each column.');
